<?php
declare(strict_types=1);
require_once __DIR__.'/../Core/Database.php';require_once __DIR__.'/../Core/View.php';
final class PaymentController
{
 private function config(string $key):string{return (string)(getenv($key)?:'');}
 public function handle():void
 {
  $provider=strtolower((string)($_GET['provider']??''));$mode=(string)($_GET['mode']??'start');$db=Database::connection();
  try{
   if($mode==='ipn'){ $this->callback($provider,$db);return; }
   if($mode==='return'){$success=$this->callback($provider,$db,false);View::render('store/payment-result.php','MobileX | Kết quả thanh toán',['success'=>$success,'provider'=>$provider]);return;}
   $userId=(int)($_SESSION['user']['id']??0);if(!$userId){header('Location: index.php?page=login');exit;}$code=trim((string)($_GET['code']??''));$q=$db->prepare("SELECT o.*,p.status payment_row_status FROM orders o JOIN payments p ON p.order_id=o.id WHERE o.order_code=? AND o.user_id=? AND o.payment_method IN ('VNPAY','MOMO') LIMIT 1");$q->execute([$code,$userId]);$order=$q->fetch(PDO::FETCH_ASSOC);if(!$order||$order['payment_row_status']!=='PENDING')throw new RuntimeException('Không tìm thấy giao dịch đang chờ.');
   $url=$order['payment_method']==='VNPAY'?$this->vnpayUrl($order):$this->momoUrl($order);header('Location: '.$url,true,303);exit;
  }catch(Throwable $e){http_response_code(400);if($mode==='ipn'){header('Content-Type: application/json; charset=utf-8');echo json_encode($provider==='vnpay'?['RspCode'=>'97','Message'=>'Invalid signature or order']:['resultCode'=>1,'message'=>'Invalid notification']);return;}View::render('store/payment-result.php','MobileX | Thanh toán',['success'=>false,'error'=>$e->getMessage(),'provider'=>$provider]);}
 }
 private function vnpayUrl(array $o):string
 {
  $tmn=$this->config('VNP_TMN_CODE');$secret=$this->config('VNP_HASH_SECRET');$base=$this->config('VNP_PAYMENT_URL')?:'https://sandbox.vnpayment.vn/paymentv2/vpcpay.html';$return=$this->config('VNP_RETURN_URL');
  if(!$tmn||!$secret||!$return)throw new RuntimeException('Thiếu cấu hình VNPAY sandbox (VNP_TMN_CODE, VNP_HASH_SECRET, VNP_RETURN_URL).');
  $params=['vnp_Version'=>'2.1.0','vnp_Command'=>'pay','vnp_TmnCode'=>$tmn,'vnp_Amount'=>(string)round((float)$o['total_amount']*100),'vnp_CurrCode'=>'VND','vnp_TxnRef'=>$o['order_code'],'vnp_OrderInfo'=>'Thanh toan don '.$o['order_code'],'vnp_OrderType'=>'other','vnp_Locale'=>'vn','vnp_ReturnUrl'=>$return,'vnp_IpAddr'=>$_SERVER['REMOTE_ADDR']??'127.0.0.1','vnp_CreateDate'=>date('YmdHis')];ksort($params);$query=http_build_query($params,'','&',PHP_QUERY_RFC3986);$params['vnp_SecureHash']=hash_hmac('sha512',$query,$secret);return $base.'?'.http_build_query($params,'','&',PHP_QUERY_RFC3986);
 }
 private function momoUrl(array $o):string
 {
  $partner=$this->config('MOMO_PARTNER_CODE');$access=$this->config('MOMO_ACCESS_KEY');$secret=$this->config('MOMO_SECRET_KEY');$ipn=$this->config('MOMO_IPN_URL');$return=$this->config('MOMO_RETURN_URL');if(!$partner||!$access||!$secret||!$ipn||!$return)throw new RuntimeException('Thiếu cấu hình MoMo sandbox (PARTNER_CODE, ACCESS_KEY, SECRET_KEY, IPN_URL, RETURN_URL).');
  $requestId=bin2hex(random_bytes(12));$amount=(string)round((float)$o['total_amount']);$info='Thanh toan don '.$o['order_code'];$extra='';$type='captureWallet';$raw="accessKey=$access&amount=$amount&extraData=$extra&ipnUrl=$ipn&orderId={$o['order_code']}&orderInfo=$info&partnerCode=$partner&redirectUrl=$return&requestId=$requestId&requestType=$type";$body=['partnerCode'=>$partner,'requestId'=>$requestId,'amount'=>$amount,'orderId'=>$o['order_code'],'orderInfo'=>$info,'redirectUrl'=>$return,'ipnUrl'=>$ipn,'requestType'=>$type,'extraData'=>$extra,'lang'=>'vi','signature'=>hash_hmac('sha256',$raw,$secret)];
  $ch=curl_init($this->config('MOMO_CREATE_URL')?:'https://test-payment.momo.vn/v2/gateway/api/create');curl_setopt_array($ch,[CURLOPT_POST=>true,CURLOPT_POSTFIELDS=>json_encode($body),CURLOPT_HTTPHEADER=>['Content-Type: application/json'],CURLOPT_RETURNTRANSFER=>true,CURLOPT_TIMEOUT=>30]);$response=curl_exec($ch);$status=(int)curl_getinfo($ch,CURLINFO_HTTP_CODE);curl_close($ch);$data=json_decode((string)$response,true);if($status>=400||empty($data['payUrl']))throw new RuntimeException('MoMo sandbox không trả liên kết thanh toán.');return (string)$data['payUrl'];
 }
 private function callback(string $provider,PDO $db,bool $ipn=true):bool
 {
  if($provider==='vnpay'){$params=$_GET;unset($params['page'],$params['provider'],$params['mode']);$received=(string)($params['vnp_SecureHash']??'');unset($params['vnp_SecureHash'],$params['vnp_SecureHashType']);ksort($params);$expected=hash_hmac('sha512',http_build_query($params,'','&',PHP_QUERY_RFC3986),$this->config('VNP_HASH_SECRET'));if(!$received||!hash_equals($expected,$received))throw new RuntimeException('Chữ ký VNPAY không hợp lệ.');$code=(string)($params['vnp_TxnRef']??'');$paid=($params['vnp_ResponseCode']??'')==='00'&&($params['vnp_TransactionStatus']??'')==='00';$transaction=(string)($params['vnp_TransactionNo']??'');}
  elseif($provider==='momo'){$d=$ipn?json_decode((string)file_get_contents('php://input'),true):$_GET;if(!is_array($d))throw new RuntimeException('Callback MoMo không hợp lệ.');$secret=$this->config('MOMO_SECRET_KEY');$access=$this->config('MOMO_ACCESS_KEY');$raw='accessKey='.$access.'&amount='.$d['amount'].'&extraData='.$d['extraData'].'&message='.$d['message'].'&orderId='.$d['orderId'].'&orderInfo='.$d['orderInfo'].'&orderType='.$d['orderType'].'&partnerCode='.$d['partnerCode'].'&payType='.$d['payType'].'&requestId='.$d['requestId'].'&responseTime='.$d['responseTime'].'&resultCode='.$d['resultCode'].'&transId='.$d['transId'];if(!hash_equals(hash_hmac('sha256',$raw,$secret),(string)($d['signature']??'')))throw new RuntimeException('Chữ ký MoMo không hợp lệ.');$code=(string)$d['orderId'];$paid=(int)$d['resultCode']===0;$transaction=(string)$d['transId'];}
  else throw new RuntimeException('Nhà cung cấp thanh toán không hợp lệ.');
  $db->beginTransaction();try{$q=$db->prepare("SELECT id,total_amount,payment_method,payment_status FROM orders WHERE order_code=? FOR UPDATE");$q->execute([$code]);$order=$q->fetch(PDO::FETCH_ASSOC);if(!$order)throw new RuntimeException('Không tìm thấy đơn hàng callback.');if($order['payment_method']!==strtoupper($provider))throw new RuntimeException('Nhà cung cấp không khớp đơn hàng.');$expectedAmount=(int)round((float)$order['total_amount']*($provider==='vnpay'?100:1));$callbackAmount=(int)($provider==='vnpay'?($params['vnp_Amount']??0):($d['amount']??0));if($expectedAmount!==$callbackAmount)throw new RuntimeException('Số tiền callback không khớp đơn hàng.');if($order['payment_status']==='PENDING'){$paymentStatus=$paid?'SUCCESS':'FAILED';$orderStatus=$paid?'PAID':'FAILED';$db->prepare('UPDATE payments SET status=?,gateway_transaction_id=?,paid_at=IF(?=\'SUCCESS\',NOW(),paid_at) WHERE order_id=?')->execute([$paymentStatus,$transaction,$paymentStatus,$order['id']]);$db->prepare('UPDATE orders SET payment_status=? WHERE id=?')->execute([$orderStatus,$order['id']]);}$db->commit();if($ipn){header('Content-Type: application/json');echo json_encode($provider==='vnpay'?['RspCode'=>'00','Message'=>'Confirm Success']:['resultCode'=>0,'message'=>'Success']);}return $paid;}catch(Throwable $e){if($db->inTransaction())$db->rollBack();throw $e;}
 }
}
